def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]

    values = {
        2017: v1,
        2018: v2,
        2019: v3,
    }

    largest_year = 2017
    if values[2018] > values[largest_year]:
        largest_year = 2018
    if values[2019] > values[largest_year]:
        largest_year = 2019

    return {
        "value": largest_year,
        "trace": {
            "values_by_year": values,
            "largest_value": values[largest_year],
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year",
            },
        },
    }
